GPU_MEM_SIZE = 80  # GB


# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """Construct four minimax placements, then polish the best with moves and swaps."""
    eps = 1e-8
    if gpu_num <= 0:
        raise ValueError("gpu_num must be positive")

    n = len(models)
    loads = [float(m.req_rate / m.slo) for m in models]
    sizes = [float(m.model_size) for m in models]
    if any(s >= GPU_MEM_SIZE - eps for s in sizes):
        raise ValueError("A model leaves no positive KV-cache memory on a GPU")

    def state(bins):
        rem = [GPU_MEM_SIZE - sum(sizes[i] for i in b) for b in bins]
        total = [sum(loads[i] for i in b) for b in bins]
        return rem, total

    def objective(bins):
        rem, total = state(bins)
        if min(rem) <= eps:
            return float("inf")
        return max(total[g] / rem[g] for g in range(gpu_num))

    orders = [
        sorted(range(n), key=lambda i: (-loads[i], -sizes[i], i)),
        sorted(range(n), key=lambda i: (-sizes[i], -loads[i], i)),
        sorted(range(n), key=lambda i: (
            -(loads[i] / sizes[i] if sizes[i] > 0 else float("inf")),
            -loads[i], -sizes[i], i)),
        sorted(range(n), key=lambda i: (
            -(loads[i] / max(GPU_MEM_SIZE - sizes[i], eps)),
            -loads[i], -sizes[i], i)),
    ]

    best = None
    best_value = float("inf")
    for order in orders:
        bins = [[] for _ in range(gpu_num)]
        for i in order:
            candidate = None
            candidate_value = float("inf")
            for g in range(gpu_num):
                if sum(sizes[j] for j in bins[g]) + sizes[i] >= GPU_MEM_SIZE - eps:
                    continue
                trial = [b[:] for b in bins]
                trial[g].append(i)
                value = objective(trial)
                if value < candidate_value:
                    candidate_value, candidate = value, trial
            if candidate is None:
                raise ValueError(
                    "Unable to find a feasible positive-residual-memory placement"
                )
            bins = candidate

        for _ in range(16):
            current = objective(bins)
            rem, total = state(bins)
            worst = max(range(gpu_num), key=lambda g: total[g] / rem[g])
            improved = None
            improved_value = current

            for pos, i in enumerate(bins[worst]):
                for g in range(gpu_num):
                    if g == worst or rem[g] - sizes[i] <= eps:
                        continue
                    trial = [b[:] for b in bins]
                    trial[worst].pop(pos)
                    trial[g].append(i)
                    value = objective(trial)
                    if value < improved_value - 1e-12:
                        improved_value, improved = value, trial

            for pos, i in enumerate(bins[worst]):
                for g in range(gpu_num):
                    if g == worst:
                        continue
                    for q, j in enumerate(bins[g]):
                        if rem[worst] + sizes[i] - sizes[j] <= eps:
                            continue
                        if rem[g] + sizes[j] - sizes[i] <= eps:
                            continue
                        trial = [b[:] for b in bins]
                        trial[worst][pos], trial[g][q] = j, i
                        value = objective(trial)
                        if value < improved_value - 1e-12:
                            improved_value, improved = value, trial

            if improved is None:
                break
            bins = improved

        value = objective(bins)
        if value < best_value:
            best_value, best = value, [b[:] for b in bins]

    return {g: [models[i] for i in best[g]] for g in range(gpu_num)}


